using System.Collections;using System.Linq;using System.Reflection;using NUnit.Framework;using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using UnityEngine.SceneManagement;using UnityEngine.TestTools;
namespace TwinkleOps.Tests {
public class V12InteractionTests {
 const string Prefix="TwinkleOps.v12.qa.";Touchscreen screen;int previousMode;InputSettings.BackgroundBehavior background;InputSettings.EditorInputBehaviorInPlayMode editorInput;
 [UnityTest] public IEnumerator TouchToggleAdsAndSearchPauseResume(){
  background=InputSystem.settings.backgroundBehavior;editorInput=InputSystem.settings.editorInputBehaviorInPlayMode;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;previousMode=PlayerPrefs.GetInt("TwinkleOps.controls.toggleAds",1);GameApp.ProgressStoreFactory=()=>new PlayerPrefsStore(Prefix);PlayerPrefs.DeleteKey(Prefix+0);PlayerPrefs.DeleteKey(Prefix+1);
  yield return SceneManager.LoadSceneAsync("Lobby");yield return null;typeof(GameApp).GetMethod("Begin",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(GameApp.Instance,null);yield return null;yield return new WaitForSeconds(.6f);
  var app=GameApp.Instance;var p=app.Player;Object.FindAnyObjectByType<InfectedDirector>().enabled=false;foreach(var z in Object.FindObjectsByType<Infected>(FindObjectsSortMode.None))z.gameObject.SetActive(false);
  screen=InputSystem.AddDevice<Touchscreen>();screen.MakeCurrent();p.SetAdsMode(true);
  void Touch(UnityEngine.InputSystem.TouchPhase phase){InputSystem.QueueStateEvent(screen,new TouchState{touchId=17,phase=phase,position=new Vector2(Screen.width*.74f,Screen.height*.28f)});}
  Touch(UnityEngine.InputSystem.TouchPhase.Began);yield return null;yield return null;Assert.IsTrue(p.AimHeld,"First touch enters ADS");Touch(UnityEngine.InputSystem.TouchPhase.Ended);yield return null;yield return null;Assert.IsTrue(p.AimHeld,"Release must retain toggle ADS");Touch(UnityEngine.InputSystem.TouchPhase.Began);yield return null;yield return null;Assert.IsFalse(p.AimHeld,"Second touch exits ADS");
  Touch(UnityEngine.InputSystem.TouchPhase.Ended);yield return null;p.SetAdsMode(false);Touch(UnityEngine.InputSystem.TouchPhase.Began);yield return null;yield return null;Assert.IsTrue(p.AimHeld);Touch(UnityEngine.InputSystem.TouchPhase.Ended);yield return null;yield return null;Assert.IsFalse(p.AimHeld,"Hold mode exits on release");
  var c=Object.FindObjectsByType<LootContainer>(FindObjectsSortMode.None).OrderBy(x=>Vector3.Distance(p.transform.position,x.transform.position)).First();var cc=p.GetComponent<CharacterController>();cc.enabled=false;p.transform.position=c.transform.position+Vector3.left;cc.enabled=true;app.OpenContainer(c);Assert.IsTrue(app.SearchOpen);Assert.IsFalse(c.Take(0,app.Session.Bag));yield return new WaitForSeconds(c.ItemSearchSeconds+.1f);Assert.GreaterOrEqual(c.RevealedCount,1);var items=c.Contents.ToArray();app.CloseInventory();float progress=c.SearchProgress;yield return new WaitForSeconds(.3f);Assert.AreEqual(progress,c.SearchProgress,.001f);app.OpenContainer(c);CollectionAssert.AreEqual(items,c.Contents);Assert.IsTrue(c.Take(0,app.Session.Bag));app.CloseInventory();
  var zones=Object.FindObjectsByType<ExtractionZone>(FindObjectsSortMode.None);var light=zones.First(z=>z.condition==ExtractionCondition.Lightweight);for(int i=0;i<5;i++)app.Session.Bag.Add("tools");Assert.IsFalse(light.Available(app));app.Session.Bag.Clear();Assert.IsTrue(light.Available(app));Assert.IsTrue(zones.Any(z=>z.condition==ExtractionCondition.None&&z.Available(app)),"Always retain a normal extraction");
  Debug.Log("V12_INTERACTION_OK");
 }
 [UnityTearDown] public IEnumerator Cleanup(){if(screen!=null)InputSystem.RemoveDevice(screen);InputSystem.settings.backgroundBehavior=background;InputSystem.settings.editorInputBehaviorInPlayMode=editorInput;PlayerPrefs.SetInt("TwinkleOps.controls.toggleAds",previousMode);PlayerPrefs.Save();if(GameApp.Instance)Object.Destroy(GameApp.Instance.gameObject);GameApp.ProgressStoreFactory=null;PlayerPrefs.DeleteKey(Prefix+0);PlayerPrefs.DeleteKey(Prefix+1);yield return null;}
}}
